"""Checksum-pinned Bubbleverse cleanup installer; local validation only."""
from pathlib import Path, PurePosixPath
import hashlib
import json
import os
import stat
import subprocess
import sys
import tempfile
import base64
import zlib

REPOSITORY='Morfindien/Bubbleverse'
BASE='b99a5c78058b624c8d5847bed582df4ea816358a'
PATCH_SHA='70327fb02612e046e8c120b8151a7309c7267f41070d8ae303f8969a31abd7e3'
PAYLOAD_SHA='0fcc443814690642bbf4ace93d083d1e570d0a78be6fbd540a9c4014b2b078d7'
PROGRAM='cleanup-installation/v330/bubbleverse_cleanup_v330.py'
WORKFLOW='.github/workflows/apply-bubbleverse-cleanup-v330.yml'
RECEIPT='cleanup-installation/v330/RECEIPT.json'
RUN='docs/maintenance/cleanup/20261024-b99a5c7-v330'
PATCH_NAME='Bubbleverse_cleanup_b99a5c7.patch'

def need(ok,message):
    if not ok:raise ValueError(message)

def safe_relative(value):
    p=PurePosixPath(value)
    need(bool(value) and not p.is_absolute() and '..' not in p.parts and '\\' not in value,'Unsafe relative path: '+value)
    return value

def local_path(root,value):
    safe_relative(value);p=root/value
    need(p.resolve().is_relative_to(root.resolve()),'Path escapes checkout: '+value)
    for ancestor in [p,*p.parents]:
        if ancestor==root:break
        need(not ancestor.is_symlink(),'Symlink is not permitted: '+value)
    return p

def sha(path):
    need(stat.S_ISREG(path.lstat().st_mode) and not path.is_symlink(),'Expected a regular file: '+str(path))
    h=hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda:f.read(1<<20),b''):h.update(block)
    return h.hexdigest()

def verify_payloads(root,expected):
    for name,spec in expected.items():
        p=local_path(root,name)
        need(p.is_file() and not p.is_symlink(),'Payload missing or symlink: '+name)
        need(sha(p)==spec['sha256'],'Payload hash mismatch: '+name)
        need(stat.S_IMODE(p.stat().st_mode)==spec['permissions'],'Payload permissions mismatch: '+name)

def validate_receipt(receipt,workflow_sha,expected_payloads,program_sha):
    expected={'schema_version':'BV-CLEANUP-ACTIONS-FILES-1','repository':REPOSITORY,'base_sha':BASE,'patch_sha256':PATCH_SHA,'payload_sha256':PAYLOAD_SHA,'program_sha256':program_sha,'workflow_sha256':workflow_sha}
    for k,v in expected.items():need(receipt.get(k)==v,'Receipt identity mismatch: '+k)
    need(receipt.get('installed_payloads')==expected_payloads,'Receipt payload inventory differs from the embedded payload and deterministic navigation updates')

def run(args,root,log=None,check=True):
    cp=subprocess.run(args,cwd=root,capture_output=True,text=True,timeout=180,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1'))
    if log is not None:log.write_text(cp.stdout+cp.stderr)
    if check and cp.returncode:raise ValueError('Command failed: '+' '.join(args)+'\n'+cp.stdout+cp.stderr)
    return cp

def navigation_updates(start_bytes,registry_bytes):
    obj=json.loads(registry_bytes)
    identifier='ENTRY-'+hashlib.sha256(('workflow:'+WORKFLOW).encode()).hexdigest()[:16]
    need(not any(e['entry_id']==identifier or e.get('source')==WORKFLOW for e in obj['entries']),'Unexpected existing installer catalog entry')
    obj['entries'].append({'entry_id':identifier,'source':WORKFLOW,'kind':'workflow','lifecycle':'ACTIVE','verification':'NOT_RUN','purpose':'Validate this exact cleanup package and optionally publish a reviewed cleanup branch; no scientific campaign','commands':['gh workflow run apply-bubbleverse-cleanup-v330.yml --repo '+REPOSITORY+' --ref main -f mode=preview','gh workflow run apply-bubbleverse-cleanup-v330.yml --repo '+REPOSITORY+' --ref main -f mode=apply'],'working_directory':'Default-branch checkout','parameters':{'mode':{'type':'choice','default':'preview','values':['preview','apply']}},'prerequisites':['Verified self-contained program installed at '+PROGRAM],'inputs':PROGRAM,'outputs':'Validated cleanup artifact; apply publishes a separate branch and attempts a PR','resume':'Not applicable','cost':'Bounded local checks; no production jobs','validation_evidence':'Local body validation is in the installer delivery; actual GitHub result belongs to this workflow run','exclusion_reason':None})
    obj['entries'].append({'entry_id':'ENTRY-'+hashlib.sha256(('python:'+PROGRAM).encode()).hexdigest()[:16],'source':PROGRAM,'kind':'python','lifecycle':'ACTIVE','verification':'NOT_RUN','purpose':'Self-contained cleanup program invoked by the Actions workflow','commands':['python '+PROGRAM],'working_directory':'Repository root on the Actions runner','parameters':{'CLEANUP_MODE':['preview','apply']},'prerequisites':['GitHub Actions environment, the matching YAML and Python 3.12'],'inputs':'Checksum-pinned embedded cleanup payload','outputs':'Validated staged cleanup and receipt','resume':'Not applicable','cost':'Bounded checks; no scientific production','exclusion_reason':None})
    appendix='\n## Cleanup installer V3.3.0\n\nSource: ['+WORKFLOW+']('+WORKFLOW+'). Upload the self-contained program to `'+PROGRAM+'`. Preview validates without publishing. Apply publishes a separate branch; merge is manual.\n\n```bash\ngh workflow run apply-bubbleverse-cleanup-v330.yml --repo '+REPOSITORY+' --ref main -f mode=preview\ngh workflow run apply-bubbleverse-cleanup-v330.yml --repo '+REPOSITORY+' --ref main -f mode=apply\n```\n'
    return {'START_CODES.md':start_bytes+appendix.encode(),RUN+'/ENTRYPOINT_REGISTRY.json':(json.dumps(obj,indent=2,ensure_ascii=False)+'\n').encode()}

def main():
    root=Path.cwd().resolve();mode=os.environ.get('CLEANUP_MODE','preview')
    need(mode in ['preview','apply'],'Unsupported cleanup mode')
    need(os.environ.get('GITHUB_REPOSITORY')==REPOSITORY,'Wrong repository; expected '+REPOSITORY)
    need(run(['git','rev-parse','--show-toplevel'],root).stdout.strip()==str(root),'Run from checkout root')
    run(['git','merge-base','--is-ancestor',BASE,'HEAD'],root)
    run(['git','diff','--exit-code'],root);run(['git','diff','--cached','--exit-code'],root)
    report=Path(os.environ['RUNNER_TEMP'])/'bubbleverse-cleanup-v330';report.mkdir(parents=True,exist_ok=True)
    program_sha=sha(local_path(root,PROGRAM))
    workflow_sha=sha(local_path(root,WORKFLOW))
    embedded=load_embedded()
    patch=embedded['patch'];manifest=embedded['manifest']
    need(manifest['repository']==REPOSITORY and manifest['base_sha']==BASE,'Embedded delivery identity mismatch')
    original_navigation={'START_CODES.md':embedded['start'],RUN+'/ENTRYPOINT_REGISTRY.json':embedded['registry']}
    updates=navigation_updates(embedded['start'],embedded['registry'])
    expected={item['repository_path']:{'sha256':item['sha256'],'permissions':item['permissions']} for item in manifest['payloads']}
    for name in expected:local_path(root,name)
    adjusted={name:dict(spec) for name,spec in expected.items()}
    for name,data in updates.items():adjusted[name]['sha256']=hashlib.sha256(data).hexdigest()
    receipt_path=local_path(root,RECEIPT)
    if receipt_path.exists():
        receipt=json.loads(receipt_path.read_text());validate_receipt(receipt,workflow_sha,adjusted,program_sha)
        verify_payloads(root,adjusted)
        need(not (root/'Bubbleverse_cleanup_24f380b.patch').exists(),'Old root patch path unexpectedly exists after installation')
        run(['python','tools/maintenance/check_cleanup_integrity.py'],root,report/'installed-integrity.json')
        (report/'result.json').write_text(json.dumps({'state':'ALREADY_APPLIED','repository':REPOSITORY,'base_sha':BASE},indent=2)+'\n')
        with Path(os.environ['GITHUB_OUTPUT']).open('a') as out:out.write('changed=false\n')
        print('ALREADY_APPLIED: verified installed files; no new branch or commit is needed.');return
    # Upload commits may add files, but must not change any original BASE_SHA file.
    changed=run(['git','diff','--name-only','--no-renames','--diff-filter=MDT',BASE,'HEAD'],root).stdout.strip()
    need(not changed,'Original source files changed since BASE_SHA; regenerate cleanup rather than overwriting:\n'+changed)
    with tempfile.TemporaryDirectory(dir=os.environ['RUNNER_TEMP'],prefix='bv-cleanup-patch-') as d:
        patch_path=Path(d)/PATCH_NAME;patch_path.write_bytes(patch)
        run(['git','apply','--index','--check',str(patch_path)],root,report/'patch-preview.log')
        run(['git','apply','--index',str(patch_path)],root,report/'patch-apply.log')
        # Git's default apply is an atomic batch; after application retain its inverse for failures.
        receipt_created=False
        try:
            verify_payloads(root,expected)
            for name,data in updates.items():(root/name).write_bytes(data)
            checks=[('integrity',['python','tools/maintenance/check_cleanup_integrity.py']),('maintenance-tests',['python','-m','unittest','discover','-s','tests/maintenance','-v']),('metadata-tests',['python','-m','unittest','-v','q048_inputcheck_tests_v1']),('v9-package',['python','q048_threshold_anchor_package_check_v9.py'])]
            for cid,args in checks:run(args,root,report/(cid+'.log'))
            verify_payloads(root,adjusted)
            receipt={'schema_version':'BV-CLEANUP-ACTIONS-FILES-1','repository':REPOSITORY,'base_sha':BASE,'patch_sha256':PATCH_SHA,'payload_sha256':PAYLOAD_SHA,'program_sha256':program_sha,'workflow_sha256':workflow_sha,'installation_upload_head':run(['git','rev-parse','HEAD'],root).stdout.strip(),'run_id':os.environ.get('GITHUB_RUN_ID','LOCAL_TEST'),'mode':mode,'state':'LOCALLY_VALIDATED_CANDIDATE','production_jobs_started':0,'installed_payloads':adjusted,'post_patch_adjustments':['START_CODES.md',RUN+'/ENTRYPOINT_REGISTRY.json'],'adjustment_reason':'Register this installer as a new technical entry point; original scientific files remain unchanged'}
            need(not receipt_path.exists(),'Receipt collision')
            with receipt_path.open('x') as f:
                receipt_created=True;f.write(json.dumps(receipt,indent=2)+'\n')
            run(['git','add','--','START_CODES.md',RUN+'/ENTRYPOINT_REGISTRY.json',RECEIPT],root)
            run(['git','diff','--cached','--check'],root,report/'diff-check.log')
            workflow_changes=run(['git','diff','--cached','--name-only','--','.github/workflows'],root).stdout.strip()
            need(not workflow_changes,'Cleanup must not rewrite workflow files')
            (report/'validated-cleanup.patch').write_text(run(['git','diff','--cached','--binary','--full-index'],root).stdout)
            (report/'change-summary.txt').write_text(run(['git','diff','--cached','--stat'],root).stdout)
            (report/'result.json').write_text(json.dumps({'state':'VALIDATED','mode':mode,'repository':REPOSITORY,'source_base':BASE,'new_native_evaluations':0,'historical_v1_package_gate':'Known pre-existing registry-pin failure; not repaired'},indent=2)+'\n')
        except Exception:
            # Restore only installer-authored mutable files to the patch's exact versions first.
            for name in ['START_CODES.md',RUN+'/ENTRYPOINT_REGISTRY.json']:
                (root/name).write_bytes(original_navigation[name])
            if receipt_created and receipt_path.exists():receipt_path.unlink()
            run(['git','restore','--staged','--',RECEIPT],root,check=False)
            run(['git','add','--','START_CODES.md',RUN+'/ENTRYPOINT_REGISTRY.json'],root)
            run(['git','apply','--index','--reverse',str(patch_path)],root)
            raise
    with Path(os.environ['GITHUB_OUTPUT']).open('a') as out:out.write('changed=true\n')
    print('CLEANUP_GATE=PASS: locally staged and verified; publication is a separate workflow step.')


def decode_blob(encoded,size,digest):
    try:
        packed=base64.b85decode(''.join(encoded.split()))
        stream=zlib.decompressobj();data=stream.decompress(packed,size+1)
    except (ValueError,zlib.error) as exc:
        raise ValueError('Embedded data decoding failed') from exc
    need(len(data)==size and stream.eof and not stream.unused_data and not stream.unconsumed_tail,'Embedded data size/stream mismatch')
    need(hashlib.sha256(data).hexdigest()==digest,'Embedded data hash mismatch')
    return data

def load_embedded():
    identity=hashlib.sha256(json.dumps(EMBEDDED_META,sort_keys=True,separators=(',',':')).encode()).hexdigest()
    need(identity==PAYLOAD_SHA,'Embedded payload identity mismatch')
    data={name:decode_blob(EMBEDDED_ENCODED[name],spec['size'],spec['sha256']) for name,spec in EMBEDDED_META.items()}
    need(hashlib.sha256(data['patch']).hexdigest()==PATCH_SHA,'Embedded patch identity mismatch')
    data['manifest']=json.loads(data['manifest'])
    return data

